INSERT INTO pages (`slug`,`title`,`subtitle`,`body`) VALUES
('policy','தமிழ்நாடு தவ்ஹீத் ஜமாஅத் - கொள்கை','அல்லாஹ்வின் இறுதி வேதம் திருக்குர்ஆன் மற்றும் முஹம்மது நபி (ஸல்) அவர்களின் தூய நபிவழியே எமது வழிகாட்டி!','<p>திருக்குர்ஆன் மற்றும் ஆதாரப்பூர்வமான நபிமொழிகள் — இவை இரண்டை மட்டுமே மார்க்கத்தின் ஆதாரமாகக் கொண்டு செயல்படும் இயக்கம் தமிழ்நாடு தவ்ஹீத் ஜமாஅத்.</p>'),
('about','எங்களைப் பற்றி','தஞ்சை வடக்கு மாவட்டம்','<p>தமிழ்நாடு தவ்ஹீத் ஜமாஅத் தஞ்சை வடக்கு மாவட்டம் — ஏகத்துவப் பிரச்சாரம், இரத்ததானம், கல்வி மற்றும் சமூக சேவைப் பணிகளில் ஈடுபட்டு வருகிறது.</p>');
INSERT INTO policy_points (`title`,`badge`,`body`,`sort_order`) VALUES
('1. தூய ஏகத்துவம் (தவ்ஹீத்)','அடிப்படை கொள்கை','அல்லாஹ் ஒருவனே வணக்கத்திற்குரியவன். அவனுக்கு யாதொரு இணையும் துணையும் இல்லை. இறந்த நல்லடியார்களிடமோ, தர்காக்களிலோ, அவ்லியாக்களிடமோ துஆ (பிரார்த்தனை) செய்வதும், நேர்ச்சை செய்வதும் கொடிய இணைவைத்தல் (ஷிர்க்) ஆகும்.',1),
('2. தூய நபிவழி (சுன்னா)','பித்அத் ஒழிப்பு','நபிகள் நாயகம் (ஸல்) அவர்களின் ஆதாரப்பூர்வமான சுன்னாவே மார்க்கத்தின் சட்டமாகும். மார்க்கத்தில் பின்னாளில் சேர்க்கப்பட்ட மீலாது விழா, மௌலிது, கந்தூரி, 3, 7, 40 பாத்திஹா போன்ற அனைத்து பித்அத்துகளும் வழிகேடாகும்.',2),
('3. வரதட்சணை மற்றும் ஆடம்பர திருமண ஒழிப்பு','சமூக சீர்திருத்தம்','மணமகனிடமிருந்து பணம், நகை, சீர்வரிசை வாங்குவது இஸ்லாத்தில் வன்மையாக கண்டிக்கப்பட்ட ஹராமான குற்றமாகும். மஹர் கொடுத்து, எளிய முறையில் பள்ளிவாசலில் நடத்தப்படும் நபிவழி நிக்காஹ்வை மட்டுமே சமூகம் பின்பற்ற வேண்டும்.',3),
('4. மனிதநேய தன்னலமற்ற சேவைகள்','மனிதநேயம்','மதம், சாதி, மொழி எல்லைகளைக் கடந்து அவசர தேவைக்கு இரத்ததானம் வழங்குதல், இயற்கை பேரிடர் காலங்களில் முன்நின்று களப்பணி ஆற்றுதல் மற்றும் ஆதரவற்ற ஏழை எளியோருக்கு வாழ்வாதார உதவி செய்தல்.',4),
('5. நளினமான முறையில் சத்தியப் பிரச்சாரம்','அழைப்புப்பணி','அனைத்து மக்களிடமும் இஸ்லாத்தின் தூய கொள்கையை பாசத்துடனும் நளினமான முறையிலும் எடுத்துரைத்தல். பிற மதத்தவரின் நம்பிக்கைகளை பழிக்காமல் ஏகத்துவத்தை தெளிவுபடுத்துதல்.',5);
